        SET week_start_date=#{weekStartDate},
            version=version+1,
            updated_at=CURRENT_TIMESTAMP
        WHERE id=#{id}
          AND user_id=#{userId}
          AND version=#{version}
          AND deleted_at IS NULL

UPDATE weekly_plan
        SET deleted_at=CURRENT_TIMESTAMP,version=version+1,updated_at=CURRENT_TIMESTAMP
        WHERE id=#{id}
          AND user_id=#{userId}
          AND version=#{version}
          AND deleted_at IS NULL

